set-var "lrn-id" get-val-public "itemId"
learnosity items [
  item metadata [
    tags {
      "Common Core": "HS-LS1-7"
      DOK: 2
      Difficulty: "medium"
    }
  ] questions [
    mcq stimulus "Which organelle is the site of aerobic respiration?"
      options [
        "Mitochondrion"
        "Chloroplast"
        "Ribosome"
        "Nucleus"
      ] valid-response [
      0
    ] metadata [
      distractor-rationale [
        "Correct — the mitochondrion is the site of aerobic respiration."
        "Confuses respiration with photosynthesis; chloroplasts capture light energy, not release it via respiration."
        "Confuses respiration with protein synthesis; ribosomes translate mRNA into proteins."
        "Confuses respiration with genetic control; the nucleus houses DNA and directs cell activity."
      ]
    ] {}
  ] {}
] {}..

