    ] metadata [
      distractor-rationale [
        "The nucleus stores genetic material and controls cell activities, but it is not the primary site of aerobic respiration."
        "Ribosomes assemble proteins from amino acids; they do not produce ATP through aerobic respiration."
        "Chloroplasts carry out photosynthesis in plant cells, whereas mitochondria perform aerobic respiration."
        "Correct — mitochondria generate most cellular ATP through aerobic respiration."
      ]
    ] {}
  ] {}
] {}..
